  "assetCandidates": [
    {
      "assetRef": "taxi_car",
      "src": "resources/base/media/icon_car.png",
      "use": "rainy taxi illustration",
      "description": "雨天打车场景的汽车图标，用于表达等车状态和出行服务。",
      "bindTo": "/taxi/carIcon",
      "static": true
    },
    {
      "assetRef": "arrival_time",
      "src": "resources/base/media/icon_time1.png",
      "use": "arrival time icon",
      "description": "雨天打车场景的时间图标，用于辅助表达预计到达时间。",
      "bindTo": "/taxi/timeIcon",
      "static": true
    }
  ]
}

